<?php
require_once dirname(__DIR__) . '/app/init.php';
if (!current_user()) { $_SESSION['_login_return'] = '/orders.php'; redirect('/login.php?return=/orders.php'); }
$customer = require_customer(); $orders = customer_orders(db(), (int) $customer['id']); $pageTitle = 'Your lovely gestures'; require dirname(__DIR__) . '/templates/header.php';
?>
<div class="container"><div class="page-heading"><p class="eyebrow">A little collection of joy</p><h1>Your lovely gestures</h1><p class="muted">Track your flowers and revisit the moments you've made.</p></div><?php if (!$orders): ?><div class="empty-state"><h2>Your first lovely gesture awaits.</h2><p>Your order history will bloom here after your first demo order.</p><a class="button" href="<?= e(url('/shop.php')) ?>">Find your flowers ↗</a></div><?php else: ?><div class="order-list"><?php foreach ($orders as $order): ?><article class="order-card"><div><h2><a href="<?= e(url('/order.php?id=' . $order['id'])) ?>"><?= e($order['order_reference']) ?></a></h2><p><?= e(date('F j, Y', strtotime($order['created_at']))) ?> · <?= $order['fulfillment_method'] === 'delivery' ? 'Delivery' : 'Store pickup' ?> on <?= e($order['scheduled_date']) ?></p></div><div class="order-card-right"><span class="status-badge <?= $order['status'] === 'cancelled' ? 'cancelled' : '' ?>"><?= e(ucwords(str_replace('_', ' ', $order['status']))) ?></span><span class="price"><?= e(format_money($order['total'])) ?></span><a class="button secondary small" href="<?= e(url('/order.php?id=' . $order['id'])) ?>">View order ↗</a></div></article><?php endforeach; ?></div><?php endif; ?></div><?php require dirname(__DIR__) . '/templates/footer.php'; ?>
